import test from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { safeMarkdown } from "../lib/markdown.js";

// Independent output audit: the only literal HTML/image introducers must be
// inside column-zero backtick fences generated by the encoder. No parser or
// entity decoding is applied twice. This covers even unresolved image refs.
function audit(source) {
  let fence = null;
  for (const line of source.split("\n")) {
    if (fence) {
      if (line === fence) fence = null;
      continue;
    }
    const match = /^(`{3,})([a-zA-Z0-9_+-]*)$/.exec(line);
    if (match) { fence = match[1]; continue; }
    assert.ok(!line.includes("<"), line);
    assert.ok(!line.includes("!"), line);
    assert.ok(!line.includes("\\"), line);
    assert.ok(!/^ {0,3}(?:`{3,}|~{3,})/.test(line), line);
    // Only entities introduced by the encoder may survive outside code.
    assert.equal(line.replace(/&(?:amp|lt|#\d+);/g, "").includes("&"), false, line);
  }
  assert.equal(fence, null, "all generated fences close");
}

const attacks = [
  '<img src="https://evil.test/a">',
  '<IMG SRC=https://evil.test/a onerror="alert(1)">',
  '<img\nsrc="https://evil.test/a">',
  '<picture><source srcset="https://evil.test/a"><img src=x></picture>',
  '<svg><image href="https://evil.test/a"/></svg>',
  '<iframe src="https://evil.test/a"></iframe><script>alert(1)</script>',
  '<style>@import "https://evil.test/a"</style>',
  '<!-- > <img src="https://evil.test/a"> -->',
  '<![CDATA[<img src="https://evil.test/a">]]><?xml x?>',
  '<<img src="https://evil.test/a"><img/src=x>',
  '![inline](https://evil.test/a "title")',
  '![nested [alt]](https://evil.test/a_(b))',
  '![ref][id]\n\n[id]: https://evil.test/a',
  '![collapsed][]\n\n[collapsed]: <https://evil.test/a>',
  '![shortcut]\n\n[shortcut]: https://evil.test/a',
  '![x][ID]\n\n[id]:\n  https://evil.test/a "title"',
  '![x\n y][id]\n\n[id]: https://evil.test/a',
  '[![nested](https://evil.test/a)](javascript:alert(1))',
  '![](./relative.png) ![](data:image/svg+xml,evil) ![](/absolute.png)',
  '&#33;[x](https://evil.test/a) &excl;[x](https://evil.test/a)',
  '&#x21;[x](https://evil.test/a) &#0000033;[x](https://evil.test/a)',
  '&lt;img src=x&gt; &#60;img src=x&#62; &#x3c;img src=x&#x3e;',
  '&amp;lt;img src=x&amp;gt; &NewLine; &Tab; &ltimg src=x>',
  '\\![x](https://evil.test/a) \\\\![x][id] \\<img src=x>',
  '\\&lt;img src=x> \\\\&#33;[x](https://evil.test/a)',
  '> ![x](https://evil.test/a)\n> <img src=x>',
  '- ![x][id]\n\n[id]: https://evil.test/a',
  '    <img src=x>\n    ![x](https://evil.test/a)',
  '> ```html\n> <img src=x>\n> ```',
  '- ```\n  <img src=x>\n  ```',
  '   ~~~\n<img src=x>\n   ~~~',
  '```bad`info\n<img src=x>\n```',
  '`unclosed <img src=x>\n![x](https://evil.test/a)',
  '[link](` <img src=x> `) ![x][id]',
  '\u0000<\u0000img src=x>\r![x](https://evil.test/a)',
];

for (const [index, input] of attacks.entries()) {
  test(`hostile source ${index + 1} is inert`, () => audit(safeMarkdown(input)));
}

test("entity encoding is single-pass, never decode then sanitize", () => {
  assert.equal(safeMarkdown('&lt;img> &#33;[x] &excl;[y]'),
    '&amp;lt;img> &amp;#33;[x] &amp;excl;[y]');
  assert.equal(safeMarkdown('![x][id]\n\n[id]: https://evil.test/a'),
    '&#33;[x][id]\n\n[id]: https://evil.test/a');
  assert.equal(safeMarkdown('<img src=x>'), '&lt;img src=x>');
});

test("common headings, lists, tables, quotes, links and ordinary code remain", () => {
  const source = '# Heading\n\n## Child\n\n- one\n- two\n\n1. first\n\n' +
    '| a | b |\n| --- | --- |\n| c | d |\n\n> quote\n\n' +
    '**bold** *italic* `code` [label](https://example.test)\n\nTitle\n=====';
  assert.equal(safeMarkdown(source), source);
});

test("root fenced code preserves literal HTML/images/entities and language", () => {
  const body = '<img src="https://evil.test/a">\n![x][id]\n&excl; &#60; \\';
  const output = safeMarkdown('```html\n' + body + '\n```\n\n![x](remote)');
  assert.ok(output.includes('```html\n' + body + '\n```'));
  assert.ok(output.endsWith('&#33;[x](remote)'));
  audit(output);
});

test("tilde code gets a collision-free fence; hostile info is not forwarded", () => {
  const body = '<img src=x>\n```\n``````\n![x](remote)';
  const output = safeMarkdown('~~~js <img src=x>\n' + body + '\n~~~');
  assert.ok(output.includes('```````js\n' + body + '\n```````'));
  audit(output);
});

test("unclosed fences, CRLF, long closers and short non-closers", () => {
  for (const source of [
    '```html\r\n<img src=x>\r\n![x](remote)',
    '````\n```\n<img src=x>\n`````\n<img src=y>',
    '~~~\n<img src=x>\n  ~~~~ \t\n![x](remote)',
    '```\n<img src=x>\n```not a closer\n![x](remote)',
    '```\n<img src=x>\n    ```\n![x](remote)',
  ]) audit(safeMarkdown(source));
});

test("generated fences are independent of surrounding containers", () => {
  for (const prefix of ['- item', '> quote', '[open', '    indented', '\\', '``']) {
    const output = safeMarkdown(prefix + '\n```html\n<img src=x>\n```\n![x](remote)');
    audit(output);
    assert.ok(output.includes('\n\n```html\n<img src=x>\n```\n\n'));
  }
});

test("sensitive inline code displays literal text without active markup", () => {
  const output = safeMarkdown('before `<img>` and `![x](url)` after');
  audit(output);
  const displayed = output.replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)));
  assert.equal(displayed, 'before <img> and ![x](url) after');
});

test("mixed syntax cannot escape its generated code fences", () => {
  let seed = 719;
  const tokens = ['<img src=x>', '![x][id]', '&lt;', '\\', '`', '``', '```', '~~~~',
    '\n', '\n\n', '> ', '- ', '    ', '[]()', '&#33;', '\r', '\u0000'];
  for (let n = 0; n < 500; n++) {
    let source = '';
    for (let i = 0; i < 40; i++) {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
      source += tokens[seed % tokens.length];
    }
    audit(safeMarkdown(source));
  }
});

// Load renderers with fluent GPUI stubs: no host or dependency is needed.
const stubUrl = 'data:text/javascript,' + encodeURIComponent(`
  export const calls = [];
  function element(kind, value) {
    const el = { kind, value, children: [], child(x) { this.children.push(x); return this; },
      on_link_click(fn) { this.handler = fn; return this; } };
    for (const name of ['flex_1', 'min_h', 'min_w', 'p', 'text_color', 'selectable', 'scrollable', 'font_family', 'text_size'])
      el[name] = function(value) { (this.styles ??= {})[name] = value; return this; };
    return el;
  }
  export const div = () => element('div');
  export const v_flex = () => element('column');
  export const TextView = { markdown(id, text) {
    calls.push({ id, text }); return element('markdown', text);
  } };
  export const EditorState = { new: options => ({ options, release() {} }) };
  export const Editor = { new: state => element('editor', state) };
`);

async function renderer(name) {
  let source = await readFile(new URL(`../renderers/${name}.js`, import.meta.url), 'utf8');
  source = source.replaceAll('"gpui-base"', JSON.stringify(stubUrl))
    .replaceAll('"gpui-kit"', JSON.stringify(stubUrl))
    .replaceAll('"../lib/markdown.js"', JSON.stringify(new URL('../lib/markdown.js', import.meta.url).href));
  return import('data:text/javascript,' + encodeURIComponent(source));
}

test("Markdown renderer uses safe source and intercepts ALL link schemes", async () => {
  const { renderMarkdown } = await renderer('markdown');
  const input = '<img src=https://evil.test/a> ![x][id]\n\n[id]: https://evil.test/a';
  const root = renderMarkdown(input, 'preview-7', { dim: '#888888' }, { font_family: 'Terminal Mono', font_size: 21 });
  const view = root.children[1];
  assert.equal(view.value, safeMarkdown(input));
  assert.equal(view.styles.selectable, true);
  assert.equal(view.styles.scrollable, true);
  assert.equal(view.styles.font_family, 'Terminal Mono');
  assert.equal(view.styles.text_size, 21);
  assert.match(root.children[0].children[0], /images\/HTML shown as text.*external links disabled/);
  const { calls } = await import(stubUrl);
  assert.equal(calls.at(-1).id, 'preview-7');
  for (const url of ['https://example.test', 'http://example.test', 'javascript:alert(1)',
    'file:///etc/passwd', 'command:run', './local.md', '#anchor', 'mailto:a@example.test']) {
    const cx = new Proxy({}, { get() { assert.fail('link action accessed context'); } });
    assert.equal(view.handler(url, cx), undefined);
  }
});

test("code renderer preserves original Files options and caller ownership", async () => {
  const { createCode, renderCode } = await renderer('code');
  const t = { ansi5: '5', ansi2: '2', dim: 'd', ansi4: '4', ansi3: '3', ansi1: '1', ansi6: '6' };
  const settings = { font_family: 'Test Mono', font_size: 21 };
  for (const [path, expected] of [['a.tsx', 'js'], ['C:\\repo\\A.MJS', 'js'],
    ['a.toml', 'yaml'], ['a.vue', 'html'], ['a.jsonc', 'json'], ['README', 'txt'], ['a.rs', 'rs']]) {
    const state = createCode('hello', path, t, settings);
    assert.equal(state.options.language, expected);
    assert.equal(state.options.value, 'hello');
    assert.equal(state.options.readonly, true);
    assert.equal(state.options.font_family, 'Test Mono');
    assert.equal(state.options.font_size, 21);
    assert.deepEqual(state.options.syntax, {
      keyword: '5', string: '2', comment: 'd', function: '4', type: '3', number: '1', constant: '6',
    });
    assert.equal(renderCode(state).value, state);
    assert.equal(typeof state.release, 'function');
  }
  assert.equal(createCode('x'.repeat(400000), 'a.js', t, settings).options.value.length, 400000);
  assert.equal(createCode('x'.repeat(400001), 'a.js', t, settings).options.value,
    'x'.repeat(400000) + '\n… (file truncated)');
});
